import { readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

const OLD = "disableTooltip", NEW = "hideHint";
const files = [];
(function walk(d) {
    for (const n of readdirSync(d)) {
        const p = join(d, n);
        if (statSync(p).isDirectory()) walk(p);
        else if (/\.(ts|html|css|scss)$/.test(n)) files.push(p);
    }
})("src");

let edits = 0, changedFiles = 0;
function renameInTag(src, selectors) {
    const re = new RegExp(`<(${selectors.join("|")})(?=[\\s/>])`, "g");
    let out = "", last = 0, m;
    while ((m = re.exec(src))) {
        let i = m.index + m[0].length, q = null;
        for (; i < src.length; i++) {
            const c = src[i];
            if (q) { if (c === q) q = null; }
            else if (c === '"' || c === "'") q = c;
            else if (c === ">") break;
        }
        const tag = src.slice(m.index, i);
        const fixed = tag
            .replace(new RegExp(`\\[${OLD}\\]`, "g"), () => (edits++, `[${NEW}]`))
            .replace(new RegExp(`(\\s)${OLD}(?=[\\s=/>]|$)`, "g"), (_, w) => (edits++, `${w}${NEW}`));
        out += src.slice(last, m.index) + fixed;
        last = i;
        re.lastIndex = i;
    }
    return out + src.slice(last);
}

for (const f of files) {
